{"task": "Find all log messages containing UUID patterns", "sql": "SELECT * FROM logs WHERE regexp_like(message, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}')"}
{"task": "Identify HTTP paths with UUID parameters", "sql": "SELECT DISTINCT path FROM events WHERE regexp_like(path, '/[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}')"}
{"task": "Count log entries with UUIDs by service", "sql": "SELECT service, COUNT(*) as uuid_count FROM logs WHERE regexp_like(message, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}') GROUP BY service"}
{"task": "Find events with UUIDs in path and status 200", "sql": "SELECT * FROM events WHERE regexp_like(path, '[0-9a-fA-F]{8}-09a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}') AND status = 200"}
{"task": "Extract UUIDs from log messages using regex", "sql": "SELECT ts, level, service, regexp_like(message, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}') as has_uuid FROM logs"}
{"task": "Find paths with UUIDs in query parameters", "sql": "SELECT path FROM events WHERE regexp_like(path, '\\?[^=&]*[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}[^=&]*=')"}
{"task": "Count distinct UUIDs in log messages", "sql": "SELECT COUNT(DISTINCT regexp_extract(message, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}')) as unique_uuids FROM logs WHERE regexp_like(message, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}')"}
{"task": "Find log messages with UUIDs in different formats", "sql": "SELECT * FROM logs WHERE regexp_like(message, '[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}') OR regexp_like(message, '[0-9a-fA-F]{32}')"}
{"task": "Analyze request paths with UUIDs by timestamp", "sql": "SELECT ts::date as date, COUNT(*) as path_count FROM events WHERE regexp_like(path, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}') GROUP BY ts::date ORDER BY date"}
{"task": "Find services that log UUIDs with error level", "sql": "SELECT DISTINCT service FROM logs WHERE regexp_like(message, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}') AND level = 'ERROR'"}

